entries[337414] = { ["name"] = "Atem des Enders", ["text"] = "12 Meter Reichweite\nWirken in 1.5 sek.\nStößt einen schattenhaften Atem aus, der Gegnern in der Nähe 50 Schattenschaden sowie zusätzlich 10 Sek. lang alle 1 Sek. 20 Schattenschaden zufügt." }
