entries[337419] = { ["name"] = "Schattensplitterzorn", ["text"] = "Wirken in 2.5 sek. 10 sek. Abklingzeit\nDer Splitterborkalptraum wird wütend und greift mit 'Schattensplitterhieb' an, wodurch jeder Nahkampfhieb 20 Schattenschaden verursacht." }
