entries[337426] = { ["name"] = "Unbearbeitete Pfeilspitzen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGeschmolzenes Phaedrum , Hölzerne Pfeilspitzenform\nQuestgegenstand\n\"Selbst ungeschliffen können sie tödlich sein.\"" }
entries[337427] = { ["name"] = "Bündel Pirscherpfeilspitzen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nUnbearbeitete Pfeilspitzen (5)\nQuestgegenstand\n\"Sehr, sehr scharf.\"" }
entries[337429] = { ["name"] = "Prankenhieb", ["text"] = "Nahkampfreichweite\nSofort\nSchlägt nach Gegnern und fügt ihnen 50 körperlichen Schaden zu." }
entries[337430] = { ["name"] = "Recht des Todes", ["text"] = "Pakt-Fähigkeit\nSofort\nVerderbt den anvisierten Boden und fügt Zielen in diesem Bereich im Verlauf von 10 Sek. [(5.4054% der Angriffskraft) * 11] Schattenschaden zu.\n\nBlut, Unheilig\nSolange Ihr Euch im Effektbereich aufhaltet [treffen 'Nekrotischer Stoß' und][trifft] [ Blut : 'Herzstoß' bis zu 0 zusätzliche Ziele und Ziele werden für 12 Sek. mit 'Recht des Todes' belegt ]['Geißelstoß' bis zu 7 Gegner in der Nähe des Ziels und Ziele werden für 12 Sek. mit 'Recht des Todes' belegt.] [\nWährend Ihr im Effektbereich verbleibt, trifft 'Auslöschen' bis zu 1 zusätzliches Ziel und Ziele werden für 12 Sek. mit 'Recht des Todes' belegt.]\n'Recht des Todes' verringert den Schaden, den Gegner Euch zufügen, um 2%, bis zu einem Maximum von 8%, und ihre verlorene Kraft wird Euch als Stärke gewährt." }
entries[337431] = { ["name"] = "Die Jagd", ["text"] = "Pakt-Fähigkeit\nSofort\nStürmt zu Eurem Ziel, fügt ihm (455% der Angriffskraft) Natur schaden zu und macht es für 1.5 Sek. bewegungsunfähig. Fügt außerdem bis zu 5 Gegnern in Eurem Weg im Verlauf von 6 Sek. (227.7% der Angriffskraft) Natur schaden zu.\n\nDie Verfolgung kräftigt Eure Seele und heilt Euch 30 Sek. lang um [ Verwüstung : 25% /\n\nRachsucht\n50% ] des Schadens, den Ihr Eurem Jagdziel zufügt." }
entries[337433] = { ["name"] = "Konvokation der Geister", ["text"] = "Pakt-Fähigkeit\nSofort\nRuft die Nachtfae an, um einen Energieausbruch auszulösen und im Verlauf von 4 Sek. 16 Druidenzauber und -fähigkeiten in schneller Folge zu kanalisieren.\n\nDabei setzt Ihr 'Wildwuchs', 'Rasche Heilung', 'Mondfeuer', 'Zorn', 'Nachwachsen', 'Verjüngung', 'Krallenhieb' oder 'Hauen' bei passenden Zielen in der Nähe ein, wobei Fähigkeiten Eurer aktuellen Gestalt bevorzugt werden." }
entries[337434] = { ["name"] = "Wilde Geister", ["text"] = "Pakt-Fähigkeit\nSofort\nRuft die Energie wilder Geister am Zielort hervor, die allen gegnerischen Zielen im Effektbereich (25% der Angriffskraft) Naturschaden zufügt und sie für 15 Sek. mit 'Wildes Mal' belegt.\n\nWährend die wilden Geister aktiv sind, fügt jede Schadensfähigkeit, die Ihr oder Euer Begleiter gegen ein Ziel im Effektbereich einsetzt, bis zu 5 zusätzlichen Zielen in der Nähe (38.5% der Angriffskraft) Naturschaden zu." }
entries[337435] = { ["name"] = "Machtverschiebung", ["text"] = "Pakt-Fähigkeit\nSofort\nZieht Kraft aus dem Boden unter Euch und fügt Gegnern innerhalb von 18 Metern im Verlauf von 4 Sek. [(60.996% der Zaubermacht) * 4] Naturschaden zu.\n\nWährend der Kanalisierung werden die Abklingzeiten Eurer Magierfähigkeiten im Verlauf von 4 Sek. um 10 Sek. verringert." }
entries[337436] = { ["name"] = "Faelinienstampfen", ["text"] = "Pakt-Fähigkeit\nSofort\nBraumeister\nSchlägt heftig auf den Boden, um für 30 Sek. eine Faelinie freizulegen. Fügt bis zu 5 von der Faelinie erfassten Gegnern innerhalb von 30 Metern (40% der Angriffskraft) Naturschaden zu und heilt bis zu 5 Verbündete in diesem Bereich um (91% der Zaubermacht) Gesundheit. 'Staffeln' ist 8 Sek. lang 5% effektiver gegen Gegner, die von der Faelinie erfasst sind.\n\nWährend Ihr auf einer Faelinie kämpft, haben Eure Fähigkeiten eine Chance von 6%, die Abklingzeit von 'Faelinienstampfen' abzuschließen.\n\nWindläufer\nSchlägt heftig auf den Boden, um für 30 Sek. eine Faelinie freizulegen. Fügt bis zu 5 von der Faelinie erfassten Gegnern innerhalb von 30 Metern (40% der Angriffskraft) Naturschaden zu und heilt bis zu 5 Verbündete in diesem Bereich um (91% der Zaubermacht) Gesundheit. Bis zu 5 Gegner, die von der Faelinie erfasst sind, und diese erleiden zusätzlich (65% der Angriffskraft) Schaden.\n\nWährend Ihr auf einer Faelinie kämpft, haben Eure Fähigkeiten eine Chance von 6%, die Abklingzeit von 'Faelinienstampfen' abzuschließen.\n\nNebelwirker\nSchlägt heftig auf den Boden, um für 30 Sek. eine Faelinie freizulegen. Fügt bis zu 5 von der Faelinie erfassten Gegnern innerhalb von 30 Metern (40% der Angriffskraft) Naturschaden zu und heilt bis zu 5 Verbündete in diesem Bereich um (91% der Zaubermacht) Gesundheit. Bis zu 5 Verbündete, die von der Faelinie erfasst sind, werden mit einem Blitz von 'Essenzborn' geheilt.\n\nWährend Ihr auf einer Faelinie kämpft, haben Eure Fähigkeiten eine Chance von 6%, die Abklingzeit von 'Faelinienstampfen' abzuschließen." }
entries[337437] = { ["name"] = "Arkanbeschuss" }
entries[337438] = { ["name"] = "Segen des Sommers", ["text"] = "Pakt-Fähigkeit\nSofort\nSegnet einen Verbündeten für 30 Sek. und gewährt seinen Angriffen so eine Chance von 40%, 30% zusätzlichen Schaden als Heiligschaden zu verursachen.\n\nSegen der Jahreszeiten: Wechselt nach dem Einsatz zum Herbst." }
entries[337439] = { ["name"] = "Faewächter", ["text"] = "Pakt-Fähigkeit\nSofort\nRuft 3 Feenwächter herbei, die sich 20 Sek. lang um Eure Ziele kümmern.\n\nZornige Fee : Direkte Angriffe auf das Ziel stellen 0.5% Mana oder 3 Wahnsinn wieder her. Folgt Eurem 'Schattenwort: Schmerz'.\n\nWächterfee : Verringert den erlittenen Schaden um 20%. Folgt Eurem 'Machtwort: Schild'.\n\nGütige Fee : Erhöht die Abklingzeitrate einer wichtigen Fähigkeit Eures Ziels um 100%. Folgt Eurer [ Heilig : 'Blitzheilung' /\n\nDisziplin, Schatten\n'Schattenheilung' ]" }
entries[337440] = { ["name"] = "Sepsis", ["text"] = "Pakt-Fähigkeit\nSofort\nInfiziert das Blut des Ziels und fügt ihm so im Verlauf von 10 Sek. (162.89% der Angriffskraft) Naturschaden zu. Wenn das Ziel die gesamte Effektdauer überlebt, erleidet es zusätzlich (77.5667% der Angriffskraft) Schaden und Ihr erhaltet 1 Einsatz einer Verstohlenheitsfähigkeit für 5 Sek.\n\nWenn 'Sepsis' nicht für die gesamte Effektdauer anhält, wird die Abklingzeit um 30 Sek. verringert.\n\nGewährt 1 Combopunkt." }
entries[337441] = { ["name"] = "Faetransfusion", ["text"] = "Pakt-Fähigkeit\nSofort\nÜberträgt die Lebenskraft von bis zu 4 Gegnern im Zielbereich und verursacht im Verlauf von 3 Sek. [((117.5% der Zaubermacht) * 3 / 0.5) + (117.5% der Zaubermacht)] Naturschaden, die gleichmäßig auf alle gegnerischen Ziele aufgeteilt werden. [ Verstärkung : Wenn 'Faetransfusion' vollständig kanalisiert wird, erzeugt Ihr 3 Stapel von 'Waffe des Mahlstroms' ]\nWenn Ihr 'Faetransfusion' innerhalb von 20 Sek. erneut einsetzt, werden 60% des gesamten Schadens von 'Faetransfusion' freigesetzt und heilen bis zu 4 Verbündete innerhalb von 20 Metern." }
entries[337442] = { ["name"] = "Rettet Gefangene" }
entries[337443] = { ["name"] = "Boss gefangen" }
entries[337444] = { ["name"] = "Seelenfäule", ["text"] = "Pakt-Fähigkeit\nSofort\nLässt die Lebenskraft Eures aktuellen Ziels und von bis zu 3 zusätzlichen Zielen in der Nähe verdorren, sodass Euer Primärziel [(100% der Zaubermacht) * 2] Naturschaden und Eure Sekundärziele (100% der Zaubermacht) Naturschaden im Verlauf von 8 Sek. erleiden.\n\nFür die nächsten 8 Sek. lässt der Einsatz von 'Blutsauger' Euch zusätzlich 'Blutsauger' gegen alle von Eurer 'Seelenfäule' betroffenen Gegner einsetzen. Außerdem verbraucht 'Blutsauger' kein Mana." }
entries[337445] = { ["name"] = "Sprung", ["text"] = "30 Meter Reichweite\nSofort\nSpringt durch die Luft und fügt bei der Landung Gegnern in der Nähe 100 Schaden zu." }
entries[337446] = { ["name"] = "Nachbeben der Ahnen", ["text"] = "Pakt-Fähigkeit\nSofort\nEntfesselt eine Animawelle, die bis zu 5 Gegnern (220% der Angriffskraft) Naturschaden zufügt und sie für 1.5 Sek. zu Boden stößt.\n\nDer Boden stößt weiterhin Anima aus, was bis zu 5 Gegnern [4 * (35% der Angriffskraft)] Naturschaden zufügt und Euch pro Gegner 16 Wut im Verlauf von 12 Sek. erzeugen lässt. Die Ziele werden alle 3 Sek. für kurze Zeit zu Boden gestoßen." }
entries[337448] = { ["name"] = "Zerschmettern", ["text"] = "Sofort\nSpringt durch die Luft und fügt bei der Landung Gegnern in der Nähe 100 Schaden zu." }
