entries[337470] = { ["name"] = "Zeichen der Anerkennung", ["text"] = "100 Meter Reichweite\nSofort\nGewährt Verbündeten, die Euch mit Heilung oder nützlichen magischen Effekten beistehen, einen Schild, der [Angriffskraft * 1.5 * (1 + Vielseitigkeit)] Schaden absorbiert. Ihr könnt Euch pro Verbündetem nur alle 20 Sek. revanchieren." }
entries[337471] = { ["name"] = "Zeichen der Anerkennung", ["text"] = "100 Meter Reichweite\nSofort\nGewährt Verbündeten, die Euch mit Heilung oder nützlichen magischen Effekten beistehen, einen Schild, der [Angriffskraft * 1.5 * (1 + Vielseitigkeit)] Schaden absorbiert. Ihr könnt Euch pro Verbündetem nur alle 20 Sek. revanchieren." }
entries[337473] = { ["name"] = "Träne des Morgens", ["text"] = "Runenschnitzmacht\nWenn ihr 'Beleben' oder 'Einhüllender Nebel' bei einem mit 'Erneuernder Nebel' belegten Ziel einsetzt, besteht eine Chance von 10%, 'Erneuernder Nebel' auf ein weiteres Ziel anzuwenden.\n\nEure bei mit 'Erneuernder Nebel' belegten Zielen durch 'Beleben' hervorgerufene Heilung ist um 20% erhöht und Euer 'Einhüllender Nebel' heilt diese Ziele zusätzlich um 20% seiner hervorgerufenen Heilung.\nRunenschnitzen: Kopf, Taille\nQuelle: Schlachtzugbeute: Schlickfaust\nBenötigt: Mönch (Nebelwirker)" }
entries[337474] = { ["name"] = "Graniteruption", ["text"] = "Sofort\nDie Haut von Grashaal verhärtet sich, was sämtlichen erlittenen Schaden um 95% verringert, bis der Effekt entfernt wird." }
entries[337476] = { ["name"] = "Umwölkter Fokus", ["text"] = "Sofort\nHeilungen mit 'Einhüllender Nebel' oder 'Beleben', während Ihr 'Beruhigender Nebel' kanalisiert, erhöhen die verursachte Heilung der beiden Fähigkeiten um 20% und verringern ihre Manakosten um 20%. Bis zu 3-mal stapelbar.\n\nWenn das Kanalisieren von 'Beruhigender Nebel' endet, wird dieser Effekt aufgehoben." }
entries[337477] = { ["name"] = "X'anshi, Rückkehr von Erzbischof Benedictus", ["text"] = "Runenschnitzmacht\nWenn Euer Geist der Erlösung abläuft, werdet Ihr mit bis zu 100% Gesundheit wiederbelebt, abhängig davon, wie effektiv Ihr als Geist der Erlösung wart. Nach Eurer Wiederbelebung kann der Geist der Erlösung 10 Min. lang nicht erneut ausgelöst werden.\nRunenschnitzen: Beine, Rücken\nQuelle: Weltbossbeute: Valinor, das Licht der Äonen\nBenötigt: Priester (Heilig)" }
entries[337478] = { ["name"] = "Splitterschüsse", ["text"] = "Sofort\nNatürliche Energie quillt aus dem Splitterborkalptraum und er verschießt Splitter von Leben und Tod auf Positionen in der Nähe." }
entries[337479] = { ["name"] = "Splitterschüsse" }
entries[337480] = { ["name"] = "Todessplitter" }
entries[337481] = { ["name"] = "Xuens Schlachtrüstung", ["text"] = "Runenschnitzmacht\nKritische Treffer mit 'Tritt der aufgehenden Sonne' verringern die Abklingzeit von 'Furorfäuste' um 5.0 Sek.\n\nBeim Ablauf von 'Furorfäuste' wird die kritische Trefferchance von 'Tritt der aufgehenden Sonne' 5 Sek. lang um 40% erhöht.\nRunenschnitzen: Brust, Rücken\nQuelle: Dungeonbeute: Kryxis der Gefräßige\nBenötigt: Mönch (Windläufer)" }
entries[337482] = { ["name"] = "Druckpunkt", ["text"] = "Sofort\nKritische Treffer mit 'Tritt der aufgehenden Sonne' verringern die Abklingzeit von 'Furorfäuste' um 5.0 Sek.\n\nBeim Ablauf von 'Furorfäuste' wird die kritische Trefferchance von 'Tritt der aufgehenden Sonne' 5 Sek. lang um 40% erhöht." }
entries[337483] = { ["name"] = "Jadezündung", ["text"] = "Runenschnitzmacht\nWenn Ihr einem Ziel mit 'Furorfäuste' Schaden zufügt, erhaltet Ihr einen Stapel Chienergie, bis zu maximal 30 Stapel.\n\nWenn Ihr 'Wirbelnder Kranichtritt' einsetzt, detoniert die Energie in einer 'Chiexplosion', die allen Gegnern innerhalb von 8 Metern (65% der Angriffskraft) Schaden zufügt. Der Schaden erhöht sich pro Stapel Chienergie um 5%.\nRunenschnitzen: Beine, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Seelenschmieden, Ebene 3+\nBenötigt: Mönch (Windläufer)" }
