entries[337485] = { ["name"] = "Klagelied von Orophea", ["text"] = "10 Meter Reichweite\nSofort\nSingt 20 Sek. lang ein Klagelied von Orophea, das Spielercharaktere innerhalb von 10 Metern unkontrolliert weinen lässt." }
