entries[337508] = { ["name"] = "Explosiver Animavorrat", ["text"] = "10 Meter Reichweite\nSofort\nFügt allen Gegnern in der Nähe Schattenschaden zu und betäubt sie für 10 Sek. Während sie betäubt sind, ist ihr erlittener Schaden um 30% erhöht." }
