entries[337532] = { ["name"] = "Halbriesenermächtigung", ["text"] = "'Metamorphose' erhöht Eure Größe, Bewegungsgeschwindigkeit und Nahkampfreichweite um 100%." }
entries[337534] = { ["name"] = "Dunkelblicksegen", ["text"] = "Runenschnitzmacht\nVerwüstung\n'Augenstrahl' hat eine Chance von 40%, keine Abklingzeit auszulösen und 30 Jähzorn zu erstatten.\n\nRachsucht\n'Dämonische Verwüstung' hat eine Chance von 40%, keine Abklingzeit auszulösen und 50 Jähzorn zu erstatten.\nRunenschnitzen: Hals, Taille\nQuelle: Dungeonbeute: Markgräfin Stradama\nBenötigt: Dämonenjäger" }
entries[337535] = { ["name"] = "Adretter Zylinder", ["text"] = "Wirken in 3 sek.\nReagenzien:\nÜbergroßer Hut , Schleierstoff (10)\nErmöglicht dem aktuell aktiven Konstrukt, den adretten Zylinder als modisches Accessoire zu tragen." }
entries[337539] = { ["name"] = "Dunkelste Stunde", ["text"] = "Runenschnitzmacht\nWenn Ihr unter 35% Gesundheit fallt, löst Ihr automatisch 'Dunkelheit' aus. Dieser Effekt kann nur einmal alle 2 Min. auftreten.\nRunenschnitzen: Brust, Beine\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Dämonenjäger" }
entries[337540] = { ["name"] = "Gesetzlosenflagge", ["text"] = "Wirken in 3 sek.\nReagenzien:\nSeltsamer Stoff , Schleierstoff (20)\nErmöglicht dem aktuell aktiven Konstrukt, die Gesetzlosenflagge als modisches Accessoire zu zeigen." }
entries[337541] = { ["name"] = "Geist der Finsterflamme", ["text"] = "Runenschnitzmacht\nEuer 'Flammendes Brandmal' heilt Euch jetzt im Verlauf von 8 Sek. um 100% des verursachten Initialschadens und jeder von Eurem 'Zeichen der Flamme' getroffene Gegner erhöht den sofortigen Schaden Eures nächsten Einsatzes von 'Flammendes Brandmal' um 15%. Bis zu 15-mal stapelbar.\nRunenschnitzen: Kopf, Hals\nQuelle: Beute von: Torghast, Turm der Verdammten. Skoldushalle, Ebene 3+\nBenötigt: Dämonenjäger (Rachsucht)" }
entries[337542] = { ["name"] = "Geist der Finsterflamme", ["text"] = "Sofort\nEuer 'Flammendes Brandmal' heilt Euch jetzt um 100% des verursachten Schadens und jeder von Eurem 'Zeichen der Flamme' getroffene Gegner erhöht den direkten Schaden Eures nächsten Einsatzes von 'Flammendes Brandmal' um 15%. Bis zu 15-mal stapelbar." }
entries[337543] = { ["name"] = "Geist der Finsterflamme", ["text"] = "Sofort\nEuer 'Flammendes Brandmal' heilt Euch jetzt im Verlauf von 8 Sek. um 100% des verursachten Initialschadens und jeder von Eurem 'Zeichen der Flamme' getroffene Gegner erhöht den sofortigen Schaden Eures nächsten Einsatzes von 'Flammendes Brandmal' um 15%. Bis zu 15-mal stapelbar." }
entries[337544] = { ["name"] = "Razelikhs Entweihung", ["text"] = "Runenschnitzmacht\n'Seelenspalter' verringert die Abklingzeit eines zufälligen Zeichens um 8 Sek.\n(500ms Abklingzeit)\nRunenschnitzen: Beine, Handgelenk\nQuelle: Dungeonbeute: Xav der Unbesiegte\nBenötigt: Dämonenjäger (Rachsucht)" }
