entries[337594] = { ["name"] = "Das Wahnsinnige Paragon", ["text"] = "Runenschnitzmacht\n'Hammer des Zorns' verursacht 30% mehr Schaden und verlängert die Dauer von [ Kreuzzug : 'Kreuzzug' ] [ Kreuzzug der Vergeltung : 'Kreuzzug der Vergeltung' / 'Zornige Vergeltung' ] um 1 Sek.\nRunenschnitzen: Taille, Füße\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Paladin" }
