entries[337598] = { ["name"] = "Alptraumhaftes Heulen", ["text"] = "Wirken in 3 sek.\nDer Splitterborkalptraum heult auf, fügt Spielercharakteren innerhalb von 12 Metern 10 Schattenschaden zu und lässt sie 5 Sek. lang vor Furcht davonlaufen.\n\nUnterbricht das Zauberwirken von Spielercharakteren außerhalb von 12 Metern und fügt Spielercharakteren, die erfolgreich unterbrochen werden, 10 Schattenschaden zu." }
entries[337599] = { ["name"] = "Nach Spielern suchen", ["text"] = "80 Meter Reichweite\nSofort\nInfiziert alle Gegner mit einer Krankheit, die 30 Sek. lang alle 1 Sek. 5 Naturschaden verursacht, wenn der Zaubernde nicht in den Nahkampf verwickelt ist.\n\nDieser Effekt ist stapelbar." }
entries[337600] = { ["name"] = "Uthers Hingabe", ["text"] = "Runenschnitzmacht\nVerringert die Abklingzeit Eurer Fähigkeiten 'Segen der Freiheit' [ Segen der Aufopferung : 'Segen der Aufopferung' ] und [ Segen des Zauberschutzes : 'Segen des Zauberschutzes' / 'Segen des Schutzes'] pro verbrauchter Heiliger Kraft um 1 Sek.\nRunenschnitzen: Hals, Brust\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Paladin" }
